import boto3


def get_s3_client():
    return boto3.client('s3', region_name='your-region')

from typing import Dict, Any


class StorageResponse:
    def __init__(self, data: Dict[str, Any]):
        self.data = data

    @staticmethod
    def normalize(response: Dict[str, Any]) -> 'StorageResponse':
        return StorageResponse(response)

import boto3
from botocore.exceptions import ClientError


def run_ocr_on_stored_document(object_name):
    textract_client = boto3.client('textract', region_name='your-region')
    try:
        response = textract_client.detect_document_text(
            Document={'S3Object':{'Bucket':'your-bucket-name','Name':object_name}}
        )
    except ClientError as e:
        raise e
    return response

import boto3
from botocore.exceptions import ClientError


def translate_text(text, source_language_code, target_language_code):
    translate_client = boto3.client('translate', region_name='your-region')
    try:
        response = translate_client.translate_text(
            Text=text,
            SourceLanguageCode=source_language_code,
            TargetLanguageCode=target_language_code
        )
    except ClientError as e:
        raise e
    return response

